<?php

declare(strict_types=1);

namespace App\Analyzer\NativeAnalyzer;

use PhpParser\Node as PhpParserNode;
use PhpParser\Node\Stmt\Class_;
use PhpParser\NodeFinder;

/**
 * The names PHPStan gives the anonymous classes of one file.
 *
 * An anonymous class has no name in the source, yet its methods are symbols the graph
 * has to be able to name, so analysis invents one. The invented name is a hash of
 * where the class stands — the file path relative to the directory the analysis runs
 * in, the line, and, when a line carries more than one of them, which one it is.
 *
 * That the name depends on the working directory is not a choice made here: it is
 * what the reference engine does, and a graph that named these classes differently
 * would not be the same graph.
 *
 * @visibility namespace
 */
final class AnonymousClassNaming
{
    /**
     * @param array<int, string> $names The invented name of each anonymous class, keyed by object id
     */
    private function __construct(
        private readonly array $names,
    ) {}

    /**
     * Invents the name of every anonymous class in a parsed file.
     *
     * Classes are numbered in the order they are written, so that two on one line are
     * told apart by their position among the classes of that line and not by anything
     * about their contents.
     *
     * @param list<PhpParserNode\Stmt> $statements   The parsed statements of the file
     * @param string                   $relativePath The file path, relative to the analysis directory
     *
     * @return self The names of that file's anonymous classes
     */
    public static function of(array $statements, string $relativePath): self
    {
        $perLine = [];
        foreach ((new NodeFinder())->find($statements, self::isAnonymous(...)) as $class) {
            assert($class instanceof Class_);
            $perLine[$class->getStartLine()][] = $class;
        }

        $names = [];
        foreach ($perLine as $line => $classes) {
            foreach ($classes as $index => $class) {
                $suffix = count($classes) === 1 ? '' : ':'.($index + 1);
                $names[spl_object_id($class)] = 'AnonymousClass'.md5($relativePath.':'.$line.$suffix);
            }
        }

        return new self($names);
    }

    /**
     * Reports whether a node is an anonymous class declaration.
     *
     * @param PhpParserNode $node A node met while walking the file
     *
     * @return bool True when the node declares a class with no name
     */
    public static function isAnonymous(PhpParserNode $node): bool
    {
        return $node instanceof Class_ && $node->name === null;
    }

    /**
     * Returns the name invented for one anonymous class.
     *
     * @param Class_ $class The anonymous class declaration
     *
     * @return string The name analysis knows that class by
     */
    public function nameOf(Class_ $class): string
    {
        return $this->names[spl_object_id($class)] ?? 'AnonymousClass'.md5(spl_object_id($class).'');
    }
}
