    /**
     * @return iterable<string, array{string}>
     */
    public static function providerExpressionsThatReachNothingNameable(): iterable
    {
        yield 'instantiating a class named by a variable' => ['new $held()'];

        yield 'calling a method on an object of unknown type' => ['$other->helper()'];

        yield 'reading a property of an object of unknown type' => ['$other->held'];

        yield 'calling a static method on a class named by a variable' => ['$held::make()'];

        yield 'calling a function named by a variable' => ['$held()'];

        yield 'reading a constant of a class named by a variable' => ['$held::ZERO'];

        yield 'adding two numbers' => ['1 + 1'];
    }

    /**
     * @return iterable<string, array{string, bool}>
     */
    public static function providerExpressionsWorthLookingAt(): iterable
    {
        yield 'instantiating a class' => ['new \App\Money()', true];

        yield 'calling a method' => ['$this->helper()', true];

        yield 'adding two numbers' => ['1 + 1', false];

        yield 'reading a variable' => ['$held', false];
    }

    /**
     * @param string      $written    The expression as it is written
     * @param null|string $className  The class it is written in, or null outside one
     * @param null|string $methodName The method it is written in, or null outside one
     *
     * @return list<string> The relations it describes, spelled out
     */
    public static function relationsOf(string $written, ?string $className, ?string $methodName): array
    {
        $index = ParsedSnippet::index(['Written.php' => "<?php\nnamespace App;\nclass Invoice {}\n"]);
        $scope = AnalysisScope::inFile($index, $index->sources()[0]->path);
        if ($className !== null) {
            $scope = $scope->enteringClass($className, null);
        }
        if ($methodName !== null) {
            $scope = $scope->enteringMethod($methodName);
        }

        return array_map(
            static fn (Edge $edge): string => $edge->from()->toString().' -['.$edge->kind()->value.']-> '.$edge->to()->toString(),
            UsageEmitter::emit(self::expressionOf($written), $scope),
        );
    }

    /**
     * @param string $written The expression as it is written
     *
     * @return PhpParserNode The parsed expression
     */
    public static function expressionOf(string $written): PhpParserNode
    {
        $statements = ParsedSnippet::statements(sprintf("<?php\nnamespace App;\n\$written = %s;\n", $written));
        $expression = (new NodeFinder())->findFirst($statements, static fn (PhpParserNode $node): bool => $node instanceof PhpParserNode\Expr\Assign);
        self::assertInstanceOf(PhpParserNode\Expr\Assign::class, $expression);

        return $expression->expr;
    }
}
